&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1/jour — &lt;a class=&quot;pagelink&quot; href=&quot;Convocation-(Capacit&#233;).html&quot; title=&quot;Convocation (Mag)&quot;&gt;convocation&lt;/a&gt; (niveau 5, 1 &lt;a class=&quot;pagelink&quot; href=&quot;Marilith.html&quot; title=&quot;D&#233;mon, Marilith&quot;&gt;marilith&lt;/a&gt; 20%, 1 &lt;a class=&quot;pagelink&quot; href=&quot;Nalfeshnie.html&quot; title=&quot;D&#233;mon, Nalfeshnie&quot;&gt;nalfeshnie&lt;/a&gt; 35% ou 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Hezrou.html&quot; title=&quot;D&#233;mon, Hezrou&quot;&gt;h&#233;zrous&lt;/a&gt; 60%)
